function seoulNow(){const f=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(serverNow()).split(':');return +f[0]*60+(+f[1]);}
const minutes=s=>s.split(':').reduce((a,v,i)=>a+Number(v)*(i===0?60:1),0);
function schedule(d){const day=new Date(d+'T12:00:00+09:00').getUTCDay();if(holidayState.dates[d])return Object.values(state.workouts).filter(w=>w.date===d).flatMap(w=>(w.sessions||[]).map(time=>({time,type:w.program,end:String(Math.floor((minutes(time)+60)/60)).padStart(2,'0')+':'+time.split(':')[1]}))).sort((a,b)=>a.time.localeCompare(b.time));if(day===0)return[];if(day===6)return[{time:'10:00',end:'20:00',type:'OPEN GYM'}];const a=day===2||day===5;let slots=[['09:30',a?'WOD':'B/T'],['11:00',a?'B/T':'WOD'],['12:00','OPEN GYM'],['17:00',a?'WOD':'B/T'],['18:00',a?'B/T':'WOD'],['19:10',a?'WOD':'B/T'],['20:30',a?'B/T':'WOD']];if(day===3)slots=slots.filter(x=>!['17:00','20:30'].includes(x[0])).map(([t,p])=>[t,p==='OPEN GYM'?p:'WOD']);return slots.map(([time,type])=>({time,type,end:type==='OPEN GYM'?'16:30':`${String(Math.floor((minutes(time)+60)/60)).padStart(2,'0')}:${time.split(':')[1]}`}));}
function activeSession(){const slots=schedule(date);if(!slots.length)return null;const now=date===today()?seoulNow():0;const slot=slots.find(s=>minutes(s.time)<=now&&minutes(s.end)>now)||slots.find(s=>minutes(s.time)>now)||slots.at(-1);return{...slot,date,current:date===today()&&minutes(slot.time)<=now&&minutes(slot.end)>now,ended:date===today()&&minutes(slot.end)<=now};}
function selected(){if(chosenSession)return chosenSession;return activeSession()}
const defaultWorkout=p=>p==='B/T'?{title:'Body Training',sections:[{title:'Find Your Front Squat',text:'Front Squat 1RM 도전!\n충분한 워밍업 후 최고 중량에 도전하세요.',record:true,kind:'1RM',movement:'Front Squat'},{title:'5 Sets · Every 3:30',text:'8 Front Squat (115 / 80 lbs)\n16 Box Step Over (Lateral)\n8 Front Squat',record:true,kind:'중량'}]}:{title:'Work of the Day',sections:[{title:'Snatch Complex · 5 Sets',text:'1 Snatch Lift Off\n1 Snatch Deadlift\n1 Snatch Pull\n1 Squat Snatch',record:true,kind:'중량'},{title:'6 Sets · Every 1:30 / Rest 1:00',text:'ODD\n20 / 18 cal Row\nMax. Power Snatch (135 / 95 lbs)\n\nEVEN\n10 Power Snatch\nMax. Cal Row',record:true,kind:'세트별 횟수·칼로리'}]};
