function workoutText(t){if(state.unit!=='kg')return esc(t);return esc(t.replace(/(\d+(?:\.\d+)?)\s*\/\s*(\d+(?:\.\d+)?) lbs/g,(_,a,b)=>`${(+a/2.2046226218).toFixed(1)} / ${(+b/2.2046226218).toFixed(1)} kg`));}
const dateLabel=d=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',weekday:'long'}).format(new Date(d+'T12:00:00+09:00'));
function datePicker(){return `<div class="date-picker date-picker-direct"><button class="date-select-button" data-action="calendar" aria-label="운동 날짜 선택" aria-haspopup="dialog">${icon('calendar')}<span>${date===today()?'오늘 · ':date===addDays(today(),1)?'내일 · ':''}${dateLabel(date)}</span><span aria-hidden="true">⌄</span></button>${date!==today()?'<button class="date-today" data-action="today">오늘로</button>':''}</div>`;}
