function setTheme(){applyTheme(savedTheme());}
function rmForm(m='Front Squat'){modal('나의 1RM 기록',`<form id="rm-form"><label class="field">운동 동작<select name="movement">${movements.map(x=>`<option ${x===m?'selected':''}>${x}</option>`).join('')}</select></label><div class="field-row"><label class="field">성공 중량<input name="weight" type="number" min="0.1" max="3000" step="0.1" required placeholder="예: 185"></label><label class="field">단위<select name="unit"><option ${state.unit==='lbs'?'selected':''}>lbs</option><option ${state.unit==='kg'?'selected':''}>kg</option></select></label></div><label class="field">측정 날짜<input type="date" name="date" value="${date}" max="${today()}" required></label><p class="field-hint">실제 성공한 1회 최대 중량을 기록해주세요.</p><div class="form-footer"><button type="button" class="btn" data-action="close">취소</button><button class="btn primary">기록 저장</button></div></form>`)}
function recordForm(id){const existing=state.records.find(r=>r.id===id);let p=existing?.program||(page==='members'?recordsFilter:program)||'WOD';let d=existing?.date||(page==='home'?selected()?.date:date)||date;const w=workout(p,d);const secs=w.sections.map((s,i)=>({...s,index:i})).filter(s=>s.record);modal(coach?'회원 운동 기록 입력':'나의 운동 기록',`<form id="record-form" data-edit-id="${id||''}"><p class="field-hint">${d} · ${p} · 이 브라우저의 미리보기에 저장됩니다.</p>${coach?`<label class="field">회원 선택<select name="memberId" required>${recordMemberOptions(existing)}</select></label>`:''}<div class="field-row"><label class="field">운동 종류<select name="program" id="record-program"><option ${p==='WOD'?'selected':''}>WOD</option><option ${p==='B/T'?'selected':''}>B/T</option></select></label><label class="field">기록 구간<select name="section" id="record-section">${secs.map(s=>`<option value="${s.index}" ${existing?.section==='S'+(s.index+1)?'selected':''}>S${s.index+1} · ${esc(s.kind)}</option>`).join('')}</select></label></div><div id="record-fields"></div><label class="field">운동 날짜<input name="date" type="date" required value="${d}" max="${today()}"></label><label class="field">메모 (선택)<input name="note" maxlength="150" placeholder="사용한 중량, 변경 동작 등" value="${esc(existing?.note||'')}"></label><div class="form-footer"><button type="button" class="btn" data-action="close">취소</button><button class="btn primary" ${secs.length?'':'disabled'}>기록 저장</button></div></form>`);recordFields(existing)}
function recordFields(existing){const f=$('#record-form');if(!f)return;const p=f.elements.program.value;const w=workout(p,f.elements.date.value||date);const sec=w.sections[+f.elements.section.value];const isWeight=sec&&['중량','1RM'].includes(sec.kind);$('#record-fields').innerHTML=!sec?'<p>이 수업은 기록을 받지 않아요.</p>':isWeight?`<div class="field-row"><label class="field">${sec.kind==='1RM'?'1RM 성공 중량':'사용 중량'}<input name="weight" type="number" min="0.1" max="3000" step="0.1" required value="${existing?.lbs?formatWeight(existing.lbs):''}" placeholder="예: 135"></label><label class="field">단위<select name="unit"><option ${state.unit==='lbs'?'selected':''}>lbs</option><option ${state.unit==='kg'?'selected':''}>kg</option></select></label></div>${sec.kind==='1RM'?'<p class="field-hint">본인 기록은 내 기록 → 1RM에도 자동으로 연결돼요.</p>':''}`:`<label class="field">${esc(sec.kind)}<input name="value" required maxlength="120" placeholder="${sec.kind==='시간'?'예: 09:35':sec.kind==='세트별 횟수·칼로리'?'예: 12 / 21 / 10 / 19 / 8 / 18':'결과를 입력하세요'}" value="${esc(existing?.value||'')}"></label>${sec.kind==='세트별 횟수·칼로리'?'<p class="field-hint">1·3·5세트: 스내치 횟수 / 2·4·6세트: 로우 칼로리</p>':''}`;}
function postModal(id){const p=allPosts().find(x=>x.id===id);if(!p)return;if(p.serverNotice)return noticePostModal(p);modal(esc(p.category),`<h2 style="font-size:21px;line-height:1.6">${esc(p.title)}</h2><div class="board-meta">${esc(p.author)} · ${p.date}</div><div class="post-body">${esc(p.body)}</div>${p.category!=='자유글'?`<button class="btn ${p.joined.includes(state.name)?'soft':'primary'} full" data-join="${id}">${icon('check')}${p.joined.includes(state.name)?'참여 취소':'참여하기'} · ${p.joined.length}명</button><p class="field-hint">${p.joined.length?'참여자: '+p.joined.map(esc).join(', '):'함께할 첫 번째 회원이 되어보세요.'}</p>`:''}<h3 style="margin-top:25px">댓글 ${p.comments.length}</h3>${p.comments.map(c=>`<div class="comment"><small>${esc(c.author)}</small>${esc(c.text)}</div>`).join('')}<form id="comment-form" data-post-id="${id}"><label class="field">댓글 남기기<input name="text" maxlength="300" placeholder="따뜻한 한마디를 남겨주세요." required></label><button class="btn primary">댓글 등록</button></form>${p.author===state.name||coach?`<button class="link" data-delete-post="${id}" style="margin-top:22px;color:#cb5762">글 삭제</button>`:''}`)}
function workoutForm(p){if(!coach)return;const w=workout(p),sections=w.sections.length?w.sections:[{title:'',text:'',record:false,kind:'없음',movements:[]},{title:'',text:'',record:false,kind:'없음',movements:[]}];modal(`${p} 수업 등록 · ${date}`,`<form id="workout-form" data-program="${p}" data-count="${sections.length}"><p class="field-hint">공개 시각: ${addDays(date,-1)} ${releaseTime} · 저장하면 서버에 반영됩니다.</p>${sections.map((sec,i)=>editorSection(sec,i)).join('')}<div id="extra-sections"></div>${holidayState.dates[date]?`<label class="field" style="margin-top:20px">${esc(holidayState.dates[date].name)} 특별 수업 시작 시각<input name="sessions" required value="${esc((w.sessions||[]).join(', '))}" placeholder="예: 10:00, 11:00"></label><p class="field-hint">공휴일은 기본 휴강입니다. 수업을 진행할 시작 시각을 지정해주세요. 각 수업은 1시간입니다.</p>`:''}<button type="button" class="btn soft" data-action="add-section">${icon('plus')}구간 추가</button><label class="field" style="margin-top:22px">오늘 운동 설명 영상 (선택)<input type="url" name="overview" placeholder="https://youtu.be/…" value="${w.overviewId?'https://youtu.be/'+w.overviewId:''}"></label><div class="form-footer"><button class="btn primary">수업 저장</button></div></form>`);}
function showInfo(){modal('현재 연결 상태','<p><strong>서버에 저장되는 항목</strong><br>출석, 날짜별 수업, 운동 사전·영상, 공지사항·홈 배너, 로그인 계정의 승인·권한입니다. 수업은 운영자가 설정한 한국 시간에 공개됩니다.</p><p><strong>현재 기기에 저장되는 미리보기 항목</strong><br>운동 결과·1RM·일반 게시글입니다. 이 항목은 아직 회원 간 공유되지 않습니다.</p><p><strong>추가 연결이 필요한 항목</strong><br>카카오 로그인입니다. 현재는 비공개 사이트 로그인으로 운영 화면을 확인할 수 있습니다.</p><button class="btn primary full" data-action="close">확인</button>');}
const actions={close,settings:()=>go('settings'),today:()=>{date=today();program=null;chosenSession=null;render()},'prev-date':()=>shiftDate(-1),'next-date':()=>shiftDate(1),record:()=>recordForm(),'rm-add':()=>rmForm(),rank:()=>{state.rank=!state.rank;state.records.filter(r=>r.name===state.name).forEach(r=>r.rank=state.rank);save();render();toast(state.rank?'순위 참여를 켰어요.':'순위 참여를 껐어요. 기록은 계속 공개돼요.')},notice:()=>{modal('ONOFF 공지사항',`<div class="post-body">${esc(bannerState.text)}</div><button class="btn primary full" data-action="close">확인</button>`)},'notice-toggle':()=>go('admin/banner'),'edit-notice':()=>go('admin/banner'),name:()=>modal('회원 이름 수정',`<form id="name-form"><label class="field">실명<input name="name" value="${esc(state.name)}" required maxlength="20" minlength="2"></label><button class="btn primary full">저장</button></form>`),kakao:()=>modal('카카오로 간편하게 시작',`<p>실서비스에서는 카카오 로그인 후 실명만 입력하면 가입을 신청할 수 있어요. 관리자 승인 후 체육관 앱을 이용합니다.</p><p class="field-hint">현재 카카오 개발자 앱이 연결되지 않아 실제 로그인·가입은 진행되지 않습니다.</p><button class="btn kakao full" disabled>카카오 로그인 · 연결 준비 중</button><button class="btn full" data-action="signup-preview">가입 신청 화면 체험</button>`),'signup-preview':()=>modal('회원 가입 신청 · 체험',`<form id="signup-form"><label class="field">체육관에서 사용하는 실명<input name="name" required minlength="2" maxlength="20" placeholder="이름을 입력해주세요"></label><p class="field-hint">실제 개인정보 수집 없이 화면 흐름을 확인하는 예시입니다. 승인된 회원에게 이름과 운동 기록이 공개되는 구조입니다.</p>${privacyLinks()}<p class="field-hint">실제 가입 전 수집·이용 및 회원 간 기록 공개 안내와 필요한 동의 절차를 확정합니다.</p><label class="checkbox-label"><input type="checkbox" required>미리보기 가입 신청임을 확인했습니다.</label><button class="btn primary full">승인 신청 체험</button></form>`),'attendance-history':()=>go('records/attendance'),attendance:async()=>{if(state.attendance.includes(today()))return toast('오늘은 이미 출석했어요.');const button=document.querySelector('[data-action="attendance"]');if(button)button.disabled=true;try{await request('/api/attendance',{});await loadServer(false);toast('오늘 출석을 완료했어요.')}catch(e){toast(e.message)}finally{if(button)button.disabled=false}},'new-post':()=>modal('우리 박스에 이야기 남기기',`<form id="post-form"><label class="field">말머리<select name="category"><option>운동 번개</option><option>공동구매</option><option>자유글</option></select></label><label class="field">제목<input name="title" required maxlength="80" placeholder="어떤 이야기를 나눌까요?"></label><label class="field">내용<textarea name="body" required maxlength="3000" placeholder="일시, 장소, 참여 방법 등을 적어주세요."></textarea></label><p class="field-hint">미리보기 글은 이 브라우저에만 저장됩니다.</p><button class="btn primary full">게시글 등록</button></form>`),'preview-info':showInfo};
function shiftDate(n){const target=addDays(date,n);if(!coach||memberPreview){if(!isReleased(target,serverNow()))return toast('해당 날짜 전날 '+releaseTime+'에 공개됩니다.')}const d=new Date(date+'T12:00:00+09:00');d.setUTCDate(d.getUTCDate()+n);date=d.toISOString().slice(0,10);program=null;chosenSession=null;render()}
document.addEventListener('click',e=>{let el=e.target.closest('button,a');if(!el)return;const d=el.dataset;if(d.memberApprove){approveMember(d.memberApprove);return}if(d.memberDetail){memberDetail(d.memberDetail);return}if(d.memberFilter){memberFilter=d.memberFilter;renderMemberResults();return}if(d.calculate){calculatorMovement=d.calculate;render();$('#weight-calculator')?.scrollIntoView({behavior:'smooth',block:'start'});return}if(d.percent){calculatorPercent=+d.percent;calc();return}if(d.noticeEdit){noticePostForm(d.noticeEdit);return}if(d.noticeDelete){confirmNoticeDelete(d.noticeDelete);return}if(d.noticeDeleteConfirm){deleteNotice(d.noticeDeleteConfirm);return}if(d.calendarDate){chooseCalendarDate(d.calendarDate);return}if(d.calendarShift){calendarMonth=addDays(calendarMonth,+d.calendarShift<0?-1:32).slice(0,7)+'-01';showCalendar();return}if(d.roleSave){updateRole(d.roleSave);return}if(d.movement){movementModal(d.movement);return}if(d.video){videoModal(d.video,d.videoTitle||'운동 설명');return}if(d.sectionRecord){recordForm();const select=$('#record-section');if(select){select.value=String(+d.sectionRecord-1);recordFields()}return}if(d.sectionHistory){sectionHistory(+d.sectionHistory-1);return}if(d.sectionResults){resultSection='S'+d.sectionResults;recordsFilter=program;go('members');return}if(d.workoutDate){date=d.workoutDate;workoutForm(d.workoutProgram);return}if(d.page)return go(d.page);if(d.action)return actions[d.action]?.();if(d.unit){state.unit=d.unit;save();return render()}if(d.program){program=d.program;return render()}if(d.session){const s=schedule(date).find(s=>s.time===d.session);chosenSession={...s,date,current:date===today()&&minutes(s.time)<=seoulNow()&&minutes(s.end)>seoulNow()};program=s.type==='B/T'?'B/T':'WOD';return render()}if(d.recordsFilter){recordsFilter=d.recordsFilter;resultSection=null;return render()}if(d.boardFilter){boardFilter=d.boardFilter;return render()}if(d.mytab){myTab=d.mytab;return render()}if(d.rm)return rmForm(d.rm);if(d.editRecord)return recordForm(d.editRecord);if(d.rmHistory){const rs=state.rms.filter(r=>r.movement===d.rmHistory).sort((a,b)=>b.date.localeCompare(a.date));return modal(esc(d.rmHistory)+' · 기록 이력',rs.length?rs.map(r=>`<div class="history-row"><span>${r.date}</span><strong>${formatWeight(r.lbs)} ${state.unit}</strong></div>`).join(''):'<div class="empty">아직 기록이 없어요.</div>')}if(d.post)return postModal(d.post);if(d.join){const p=state.posts.find(p=>p.id===d.join);p.joined=p.joined.includes(state.name)?p.joined.filter(n=>n!==state.name):[...p.joined,state.name];save();render();return postModal(p.id)}if(d.deletePost){const p=state.posts.find(p=>p.id===d.deletePost);if(!p||(!coach&&p.author!==state.name))return;modal('게시글 삭제',`<p>이 게시글과 댓글을 삭제할까요?</p><div class="form-footer"><button class="btn" data-post="${p.id}">돌아가기</button><button class="btn primary" data-confirm-delete="${p.id}">삭제하기</button></div>`);return}if(d.confirmDelete){state.posts=state.posts.filter(p=>p.id!==d.confirmDelete);save();close(true);render();return toast('게시글을 삭제했어요.')}if(d.editWorkout)return workoutForm(d.editWorkout);if(d.approve&&coach){const m=state.members.find(m=>m.id===d.approve);m.status='approved';save();render();toast(`${m.name}님의 체험 승인을 완료했어요.`)}});
document.addEventListener('change',async e=>{if(e.target.id==='excel-file'){await excelFile(e.target.files[0]);e.target.value='';return}if(e.target.id==='date-input'){if((!coach||memberPreview)&&!isReleased(e.target.value,serverNow())){toast('해당 날짜 전날 '+releaseTime+'에 공개됩니다.');e.target.value=date;return}date=e.target.value||today();program=null;chosenSession=null;render()}if(e.target.id==='calc-movement')calc();if(e.target.id==='record-program'){const f=$('#record-form'),w=workout(f.elements.program.value,f.elements.date.value||date);$('#record-section').innerHTML=w.sections.map((s,i)=>s.record?`<option value="${i}">S${i+1} · ${esc(s.kind)}</option>`:'').join('');recordFields()}if(e.target.id==='record-section')recordFields();if(e.target.matches('#record-form [name="date"]')){const f=$('#record-form'),w=workout(f.elements.program.value,e.target.value);$('#record-section').innerHTML=w.sections.map((s,i)=>s.record?`<option value="${i}">S${i+1} · ${esc(s.kind)}</option>`:'').join('');recordFields()}if(e.target.id==='library-search'){librarySearch=e.target.value;render()}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f));const id=crypto.randomUUID();if(await extraForm(f,data))return;if(await serverForm(f,data))return;if(f.id==='rm-form'){state.rms.push({id,movement:data.movement,lbs:+data.weight*(data.unit==='kg'?2.2046226218:1),date:data.date});save();close(true);render();return toast('새로운 도전을 1RM에 기록했어요.')}if(f.id==='record-form'){const w=workout(data.program,data.date),s=w.sections[+data.section];if(!s?.record)return toast('이 구간은 기록을 받지 않아요.');const old=state.records.find(r=>r.id===f.dataset.editId);if(old&&!coach&&old.name!==state.name)return;const r={...old,movement:s.movement||'',movements:s.movements||[],id:old?.id||id,name:coach?state.members.find(m=>m.id===data.memberId)?.name||'':state.name,memberId:coach?data.memberId:viewer.id,date:data.date,program:data.program,section:'S'+(+data.section+1),kind:s.kind,rank:old?.rank??state.rank,note:data.note,writer:coach?'admin':'member'};delete r.lbs;delete r.value;if(old?.session&&(old.program!==data.program||old.date!==data.date))delete r.session;if(r.name===state.name)r.memberId=viewer.id;if(data.weight)r.lbs=+data.weight*(data.unit==='kg'?2.2046226218:1);else r.value=data.value;if(!r.name||(!r.lbs&&!r.value?.trim()))return toast('기록 내용을 입력해주세요.');if(old)state.records[state.records.indexOf(old)]=r;else state.records.push(r);state.rms=state.rms.filter(x=>x.source!==r.id);if(s.kind==='1RM'&&r.name===state.name&&r.lbs)state.rms.push({id,source:r.id,movement:s.movement||'Front Squat',lbs:r.lbs,date:r.date});save();close(true);render();return toast('운동 기록을 저장했어요.')}if(f.id==='post-form'){if(!data.title.trim()||!data.body.trim())return;state.posts.unshift({id,category:data.category,title:data.title.trim(),body:data.body.trim(),author:state.name,date:today(),joined:[],comments:[]});save();close(true);render();return toast('새 이야기를 등록했어요.')}if(f.id==='comment-form'){if(!data.text.trim())return;const p=state.posts.find(p=>p.id===f.dataset.postId);p.comments.push({author:state.name,text:data.text.trim()});save();unsaved.track($('#modal-body'));return postModal(p.id)}if(f.id==='notice-form'&&viewer?.role==='admin'){if(!data.notice.trim())return;state.notice=data.notice.trim();save();close(true);render();return toast('공지 문구를 저장했어요.')}if(f.id==='signup-form'){state.members.push({id,name:data.name.trim(),status:'pending'});save();unsaved.track($('#modal-body'));modal('가입 신청 완료 · 체험','<p>관리자가 회원 확인 후 승인하는 단계입니다.</p><p class="field-hint">실제 가입은 진행되지 않았어요. 운영자 화면에서 체험 신청을 확인할 수 있습니다.</p><button class="btn primary full" data-action="close">확인</button>');return}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1)||'login';if(p!==page){if(!unsaved.allow()){history.replaceState(null,'','#'+page);return}if($('#modal').open)close(true);page=p;render()}});

function tick(){$('#live-clock').textContent=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(serverNow())+' KST'}
setTheme();render();tick();loadServer();setInterval(()=>{tick();if(!$('#modal').open&&!document.hidden&&!$('#main form'))loadServer(false)},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!$('#modal').open&&!$('#main form'))loadServer(false)});

async function request(path,body){if(globalThis.ONOFF_DEMO)return demoRequest(path,body);const opts=body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{};const res=await fetch(path,opts);let data;try{data=await res.json()}catch{throw new Error('서버 응답을 확인할 수 없어요. 잠시 후 다시 시도해주세요.')}if(!res.ok){const e=new Error(data.error||'요청을 처리하지 못했어요.');Object.assign(e,data,{status:res.status});throw e}return data;}
async function loadServer(showLoading=true){if(showLoading)loading=true;try{const data=await request('/api/bootstrap'+(memberPreview?'?view=member':''));bannerState=data.banner||{...DEFAULT_BANNER};pushState=data.push||pushState;devicePushEnabled=!!await deviceSubscription();releaseTime=data.releaseTime||'22:00';publishedDates=data.publishedDates||[];notices=data.notices||[];if(data.calendar)holidayState=data.calendar;viewer=data.viewer;selfMembership=data.membership||null;selfMembershipAccess=data.membershipState?.active??true;memberships=data.memberships||[];membershipEvents=data.membershipEvents||[];memberAttendance=data.memberAttendance||[];tvSettings=data.tv||{};serverOffset=Date.parse(data.serverNow)-Date.now();state.attendance=data.attendance||[];state.workouts=data.workouts||{};state.members=data.members||[];libraryState=data.library||[];state.name=viewer.name;coach=viewer.role==='admin'&&viewer.status==='approved';apiError='';loading=false;render();nextReleaseRefresh();return data;}catch(e){loading=false;if(showLoading||!viewer){apiError=e.message;render()}else toast(e.message);return null}}
function sectionCard(sec,i){const ms=sec.movements?.length?sec.movements:sec.movement?[sec.movement]:[];return `<div class="workout-section"><div class="section-mark">S${i+1}</div><details class="section-details" open><summary class="section-heading"><h3>${esc(sec.title)}</h3>${sec.record?`<span class="mini-badge">${esc(sec.kind)} 기록</span>`:''}</summary><div class="exercise">${workoutText(sec.text)}</div><div>${ms.map(name=>{const m=libraryState.find(m=>m.name===name);return `<button class="video-link" data-movement="${esc(name)}">${m?.videoId?'▶':'↗'} ${esc(name)} ${m?.videoId?'동작 영상':'알아보기'}</button>`}).join('')}</div>${sec.record?`<div class="section-tools"><button data-section-history="${i+1}">${icon('clock')} 내 기록</button><button data-section-results="${i+1}">${icon('users')} 회원 결과</button><button class="log-result" data-section-record="${i+1}" ${date>today()?'disabled':''}>${icon('edit')} 기록 입력</button></div>`:''}</details></div>`;}
function libraryPage(){return `${intro('좋은 움직임의 시작','동작을 배우고, 내 기록을 확인해보세요.')}<div class="library-page-head"><input type="search" id="library-search" class="search-input" placeholder="동작 검색 · 예: Front Squat" aria-label="동작 검색" value="${esc(librarySearch)}">${coach?'<button class="btn primary" data-action="movement-add">'+icon('plus')+'동작 등록</button>':''}</div><div class="library-grid" id="library-cards">${libraryCards()}</div>`;}
function libraryCards(){return libraryState.filter(m=>m.name.toLowerCase().includes(librarySearch.toLowerCase())).map(m=>`<button class="panel movement-card" data-movement="${esc(m.name)}"><h3>${esc(m.name)}</h3><p>${m.videoId?'▶ 동작 설명 영상':'동작 설명 영상 준비 중'}${best(m.name)?' · 내 최고 '+formatWeight(best(m.name).lbs)+' '+state.unit:''}</p></button>`).join('')||'<div class="empty">검색 결과가 없어요.</div>';}
function movementModal(name){const m=libraryState.find(x=>x.name===name)||{name,notes:'',videoId:''},b=best(name);modal(esc(name),`${m.videoId?`<button class="btn primary full" data-video="${m.videoId}" data-video-title="${esc(name)}">▶ 동작 설명 영상 보기</button>`:'<div class="empty">운동 설명 영상을 준비 중이에요.</div>'}${m.notes?`<div class="post-body">${esc(m.notes)}</div>`:''}<div class="history-row"><span>나의 1RM</span><strong>${b?formatWeight(b.lbs)+' '+state.unit:'아직 기록이 없어요'}</strong></div><button class="btn soft full" data-rm-history="${esc(name)}">내 1RM 기록 이력</button>${coach?`<button class="btn full" data-movement-edit="${esc(name)}">영상·설명 수정</button>`:''}`);}
function videoModal(id,title){if(!/^[\w-]{11}$/.test(id))return;modal(esc(title),`<iframe class="video-frame" src="https://www.youtube-nocookie.com/embed/${id}" title="${esc(title)}" allow="accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><a class="btn full" href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener noreferrer">유튜브에서 보기 ↗</a><p class="field-hint">재생되지 않으면 유튜브에서 열어주세요.</p>`);}
function movementForm(name=''){if(!coach)return;const m=libraryState.find(x=>x.name===name)||{name,videoId:'',notes:''};modal(name?'운동 영상·설명 수정':'운동 동작 등록',`<form id="movement-form"><label class="field">동작 이름<input name="name" required maxlength="80" minlength="2" value="${esc(m.name)}" ${name?'readonly':''} placeholder="예: Front Squat"></label><label class="field">유튜브 영상 주소 (선택)<input name="url" type="url" value="${m.videoId?'https://youtu.be/'+m.videoId:''}" placeholder="https://youtu.be/…"></label><label class="field">동작 설명·코칭 포인트<textarea name="notes" maxlength="1000">${esc(m.notes)}</textarea></label><p class="field-hint">영상 없이 동작부터 등록해도 됩니다. 관련 동작이 지정된 모든 수업에 연결됩니다.</p><button class="btn primary full">저장</button></form>`);}
function sectionHistory(index){const sec=workout().sections[index];if(!sec)return;const ms=sec.movements?.length?sec.movements:sec.movement?[sec.movement]:[];const rows=state.records.filter(r=>r.name===state.name&&(ms.length?ms.some(m=>r.movement===m||r.movements?.includes(m)):r.program===program&&r.section==='S'+(index+1)));modal('나의 운동 기록',`<p class="field-hint">${ms.length?ms.map(esc).join(' · '):esc(sec.title)}</p>${rows.length?rows.slice().reverse().map(r=>`<div class="history-row"><div>${esc(r.date)}<small>${r.program} · ${r.section}</small></div><strong>${resultValue(r)}</strong></div>`).join(''):'<div class="empty">아직 남긴 기록이 없어요.</div>'}`);}
function editorSection(sec,i){return `<section class="record-form-section"><h3>S${i+1}</h3><label class="field">구간 제목<input name="title${i}" value="${esc(sec.title||'')}" required maxlength="100"></label><label class="field">운동 내용<textarea name="text${i}" required maxlength="5000">${esc(sec.text||'')}</textarea></label><label class="checkbox-label"><input type="checkbox" name="record${i}" ${sec.record?'checked':''}>이 구간 기록 받기</label><label class="field">기록 종류<select name="kind${i}">${KINDS.filter(k=>k!=='없음').map(k=>`<option ${sec.kind===k?'selected':''}>${k}</option>`).join('')}</select></label><label class="field">관련 동작 (여러 개는 ;로 구분)<input name="movements${i}" value="${esc((sec.movements?.length?sec.movements:sec.movement?[sec.movement]:[]).join('; '))}" placeholder="Front Squat; Row"></label><p class="field-hint">1RM은 동작을 하나 지정해주세요. 운동 사전에 등록된 이름을 사용합니다.</p></section>`;}
let xlsxReady;
async function loadXlsx(){if(window.XLSX)return window.XLSX;if(!xlsxReady)xlsxReady=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='assets/xlsx.full.min.js';script.onload=()=>resolve(window.XLSX);script.onerror=()=>{xlsxReady=null;script.remove();reject(new Error('엑셀 읽기 기능을 불러오지 못했어요. 다시 시도해주세요.'))};document.head.appendChild(script)});return xlsxReady;}
async function excelFile(file){if(!file)return;if(!coach)return toast('수업 관리 권한이 필요해요.');if(!file.name.toLowerCase().endsWith('.xlsx'))return toast('.xlsx 파일을 선택해주세요.');if(file.size>3*1024*1024)return toast('3MB 이하 파일을 선택해주세요.');modal('엑셀 파일 확인 중','<p>수업 내용과 날짜를 확인하고 있어요…</p>');try{const XLSX=await loadXlsx(),book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});const sheet=book.Sheets['수업등록'];if(!sheet)throw new Error('수업등록 시트가 없어요. 제공된 양식을 사용해주세요.');const range=XLSX.utils.decode_range(sheet['!ref']||'A1');if(range.e.r>1000)throw new Error('최대 1,000행까지 등록할 수 있어요.');const head=XLSX.utils.sheet_to_json(sheet,{header:1,range:0,raw:false})[0]||[];const missing=HEADERS.slice(0,6).filter(h=>!head.includes(h));if(missing.length)throw new Error('필수 열이 없어요: '+missing.join(', '));const rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:false,dateNF:'yyyy-mm-dd'});const validated=normalizeRows(rows,libraryState.map(m=>m.name),holidayState.dates);if(validated.errors.length){importWorkouts=[];return modal('엑셀 내용을 확인해주세요',`<div class="import-error">${validated.errors.slice(0,40).map(esc).join('<br>')}</div><p class="field-hint">아직 저장된 내용은 없습니다. 오류를 수정한 뒤 다시 올려주세요.</p><button class="btn full" data-action="close">닫기</button>`)}if(!validated.workouts.length)throw new Error('등록할 수업이 없어요. 수업등록 시트에 내용을 작성해주세요.');importWorkouts=validated.workouts;importPreview(file.name);}catch(e){importWorkouts=[];modal('파일을 확인해주세요',`<p>${esc(e.message)}</p><button class="btn full" data-action="close">확인</button>`);}}
function importPreview(filename='선택한 파일',serverCollisions=[]){const overlaps=serverCollisions.length?serverCollisions:importWorkouts.filter(w=>state.workouts[w.date+'_'+w.program]).map(w=>w.date+' '+w.program);modal('수업 일괄 등록 미리보기',`<p><strong>${esc(filename)}</strong><br>${importWorkouts.length}개 수업 · ${importWorkouts.reduce((a,w)=>a+w.sections.length,0)}개 구간</p><div class="upload-preview"><table class="import-table"><thead><tr><th>날짜</th><th>수업</th><th>구간</th><th>공개</th></tr></thead><tbody>${importWorkouts.map(w=>`<tr><td>${w.date}</td><td>${w.program}</td><td>${w.sections.length}개</td><td>${isReleased(w.date,serverNow())?'등록 즉시 공개':addDays(w.date,-1)+' '+releaseTime}</td></tr>`).join('')}</tbody></table></div>${overlaps.length?`<div class="import-error">기존 수업과 ${overlaps.length}개가 겹쳐요.<br>${overlaps.slice(0,8).map(esc).join('<br>')}</div><label class="checkbox-label"><input type="checkbox" id="overwrite-check">기존 수업 내용을 이 파일의 내용으로 덮어씁니다.</label>`:''}<p class="field-hint">저장 전입니다. 날짜와 수업 내용을 확인해주세요. 미래 수업은 전날 ${releaseTime}에 공개됩니다.</p><div class="form-footer"><button class="btn" data-action="close">취소</button><button class="btn primary" data-action="import-save">${importWorkouts.length}개 수업 등록</button></div>`);}
async function importSave(){if(!coach||!importWorkouts.length)return;const check=$('#overwrite-check');if(check&&!check.checked)return toast('기존 수업 덮어쓰기를 확인해주세요.');const button=$('[data-action="import-save"]');button.disabled=true;try{const result=await request('/api/workouts',{workouts:importWorkouts,overwrite:!!check?.checked});importWorkouts=[];await loadServer(false);close(true);toast(`${result.count}개 수업을 등록했어요. 전날 ${releaseTime}에 공개됩니다.`)}catch(e){if(e.status===409)return importPreview('선택한 파일',e.collisions);toast(e.errors?.[0]||e.message);button.disabled=false;}}
async function updateRole(id){if(viewer?.role!=='admin')return;const role=document.getElementById('role-'+id)?.value,status=document.getElementById('status-'+id)?.value;try{await request('/api/members',{id,role,status});await loadServer(false);toast('회원 권한을 저장했어요.')}catch(e){toast(e.message)}}
async function serverForm(f,data){if(await communitySettingsForm(f,data))return true;if(!['workout-form','movement-form','name-form','profile-pending-form'].includes(f.id))return false;const submit=f.querySelector('button:not([type="button"])');if(submit)submit.disabled=true;try{if(f.id==='workout-form'){if(!coach)return true;const sections=Array.from({length:+f.dataset.count},(_,i)=>({title:data['title'+i],text:data['text'+i],record:data['record'+i]==='on',kind:data['kind'+i],movements:(data['movements'+i]||'').split(';').map(v=>v.trim()).filter(Boolean)}));const overviewId=data.overview?youtubeId(data.overview):'';if(overviewId===null)throw new Error('유효한 유튜브 영상 주소를 입력해주세요.');const validated=validateWorkouts([{date,program:f.dataset.program,sections,overviewId,sessions:(data.sessions||'').split(',').map(v=>v.trim()).filter(Boolean)}],libraryState.map(m=>m.name),holidayState.dates);if(validated.errors.length)throw new Error(validated.errors[0]);await request('/api/workouts',{workouts:validated.workouts,overwrite:true});}else if(f.id==='movement-form'){await request('/api/movements',data);}else{const old=state.name;await request('/api/profile',{name:data.name});state.records.filter(r=>r.name===old).forEach(r=>r.name=data.name.trim());save();}await loadServer(false);close(true);toast('저장했어요.');}catch(e){toast(e.errors?.[0]||e.message);}finally{if(submit)submit.disabled=false}return true;}
Object.assign(actions,{'tomorrow':()=>{const d=addDays(today(),1);if(!coach||memberPreview){if(!isReleased(d,serverNow()))return toast('내일 운동은 '+releaseTime+'에 공개됩니다.')}date=d;program=null;chosenSession=null;go('home')},'member-preview':async()=>{if(!coach)return;memberPreview=!memberPreview;await loadServer(false);go(memberPreview?'home':'admin')},'retry':()=>loadServer(),'movement-add':()=>movementForm(),'import-save':importSave,'add-section':()=>{const f=$('#workout-form');if(!f)return;const n=+f.dataset.count;if(n>=99)return;$('#extra-sections').insertAdjacentHTML('beforeend',editorSection({},n));f.dataset.count=String(n+1);}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(el?.dataset.movementEdit)movementForm(el.dataset.movementEdit)});
document.addEventListener('input',e=>{if(e.target.id==='library-search'){librarySearch=e.target.value;$('#library-cards').innerHTML=libraryCards()}});
$('#modal').addEventListener('close',()=>{$('#modal-body').querySelectorAll('iframe').forEach(f=>f.remove());importWorkouts=[]});

function nextReleaseRefresh(){clearTimeout(releaseTimer);const next=releaseAt(addDays(today(),1));const target=+serverNow()<next?next:releaseAt(addDays(today(),2));releaseTimer=setTimeout(async()=>{if(!document.hidden&&!$('#modal').open)await loadServer(false);nextReleaseRefresh()},Math.max(1000,target-(+serverNow())+100));}

function allPosts(){return [...notices,...state.posts].sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned)||(b.created_at||b.date).localeCompare(a.created_at||a.date));}
function noticePostModal(p){modal('공지사항',`${p.pinned?'<span class="tag notice-tag">📌 상단 고정</span>':''}<h2 style="margin-top:13px">${esc(p.title)}</h2><div class="board-meta">${esc(p.author)} · ${p.date}</div><div class="post-body">${esc(p.body)}</div>${viewer?.role==='admin'?`<div class="form-footer"><button class="btn" data-notice-delete="${p.id}">삭제</button><button class="btn primary" data-notice-edit="${p.id}">수정·고정 설정</button></div>`:''}`);}
function noticePostForm(id){if(viewer?.role!=='admin')return;const p=notices.find(p=>p.id===id);if(!p)return;modal('공지사항 수정',`<form id="notice-post-form" data-notice-id="${p.id}"><label class="field">제목<input name="title" required maxlength="100" value="${esc(p.title)}"></label><label class="field">내용<textarea name="body" required maxlength="5000">${esc(p.body)}</textarea></label><label class="checkbox-label"><input name="pinned" type="checkbox" ${p.pinned?'checked':''}>커뮤니티 상단에 고정</label><label class="checkbox-label notice-push-option"><input name="sendPush" type="checkbox">알림을 켠 회원에게 공지 푸시 보내기</label><button class="btn primary full">공지 저장</button></form>`);}
function confirmNoticeDelete(id){if(viewer?.role!=='admin')return;modal('공지사항 삭제','<p>이 공지사항을 삭제할까요?</p><div class="form-footer"><button class="btn" data-action="close">취소</button><button class="btn primary" data-notice-delete-confirm="'+esc(id)+'">삭제</button></div>');}
async function deleteNotice(id){try{await request('/api/notices',{id,action:'delete'});await loadServer(false);close(true);toast('공지를 삭제했어요.')}catch(e){toast(e.message)}}
async function communitySettingsForm(f,data){const noticeForm=f.id==='notice-post-form'||f.id==='post-form'&&data.category==='공지사항';if(!noticeForm&&f.id!=='release-time-form')return false;if(viewer?.role!=='admin'){toast('운영자 권한이 필요해요.');return true}const submit=f.querySelector('button:not([type="button"])');if(submit)submit.disabled=true;try{if(noticeForm)await request('/api/notices',{id:f.dataset.noticeId||undefined,title:data.title,body:data.body,pinned:data.pinned==='on',sendPush:data.sendPush==='on'});else await request('/api/settings',{releaseTime:data.releaseTime});await loadServer(false);close(true);toast(noticeForm?'공지를 저장했어요.':'운동 공개 시각을 '+releaseTime+'로 변경했어요.');}catch(e){toast(e.message)}finally{if(submit)submit.disabled=false}return true;}
function monthGrid(month,interactive=true){const year=+month.slice(0,4),m=+month.slice(5,7),days=new Date(year,m,0).getDate(),offset=new Date(month+'T12:00:00+09:00').getUTCDay();return `<div class="calendar holiday-calendar">${['일','월','화','수','목','금','토'].map((d,i)=>`<span class="weekday ${i===0?'holiday-day':''}">${d}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=month.slice(0,8)+String(i+1).padStart(2,'0'),h=holidayState.dates[d],cls=[h?'holiday-day':'',state.attendance.includes(d)?'attended':'',d===today()?'today':'',d===date?'selected-day':''].join(' '),body=`${i+1}${state.attendance.includes(d)?' ✓':''}${h?'<small>'+esc(h.name)+'</small>':''}`;return interactive?`<button class="${cls}" ${!coach||memberPreview?!isReleased(d,serverNow())?'disabled':'':''} data-calendar-date="${d}" aria-label="${d}${h?' '+esc(h.name):''}">${body}</button>`:`<span class="${cls}">${body}</span>`}).join('')}</div>`;}
function showCalendar(){if(!calendarMonth)calendarMonth=date.slice(0,7)+'-01';modal('대한민국 공휴일 달력',`<div class="month-nav"><button class="btn" data-calendar-shift="-1" aria-label="이전 달">‹</button><strong>${calendarMonth.slice(0,4)}년 ${+calendarMonth.slice(5,7)}월</strong><button class="btn" data-calendar-shift="1" aria-label="다음 달">›</button></div>${monthGrid(calendarMonth)}<p class="field-hint">빨간 날짜는 공휴일·대체공휴일입니다. 기본 휴강이며 등록된 특별 수업이 있으면 표시됩니다.</p><p class="field-hint">${esc(holidayState.source)}${holidayState.fallback||holidayState.stale?' · 저장된 일정 사용 중':''}</p>`);}
function chooseCalendarDate(d){if((!coach||memberPreview)&&!isReleased(d,serverNow()))return toast('해당 날짜 운동은 전날 '+releaseTime+'에 공개됩니다.');date=d;chosenSession=null;program=null;close();render();}
Object.assign(actions,{'calendar':()=>{calendarMonth=date.slice(0,7)+'-01';showCalendar()},'sync-holidays':async()=>{try{const response=await request('/api/holidays/sync',{});holidayState=response.calendar;render();toast(holidayState.fallback||holidayState.stale?'최신 일정을 불러오지 못해 저장된 일정을 유지했어요.':'대한민국 공휴일 일정을 새로고침했어요.')}catch(e){toast(e.message)}},'new-post':()=>modal('우리 박스에 이야기 남기기',`<form id="post-form"><label class="field">말머리<select name="category" id="post-category">${viewer?.role==='admin'?'<option>공지사항</option>':''}<option>운동 번개</option><option>공동구매</option><option>자유글</option></select></label><label class="field">제목<input name="title" required maxlength="100"></label><label class="field">내용<textarea name="body" required maxlength="5000"></textarea></label>${viewer?.role==='admin'?'<label class="checkbox-label" id="post-pin-label"><input name="pinned" type="checkbox">커뮤니티 상단에 고정</label><label class="checkbox-label notice-push-option"><input name="sendPush" type="checkbox">알림을 켠 회원에게 공지 푸시 보내기</label>':''}<p class="field-hint">공지사항은 운영자만 작성할 수 있고, 서버에 저장됩니다. 일반 게시글은 아직 현재 기기의 미리보기입니다.</p><button class="btn primary full">게시글 등록</button></form>`)});
document.addEventListener('change',e=>{if(e.target.id==='post-category'&&$('#post-pin-label')){document.querySelectorAll('.notice-push-option').forEach(label=>{label.hidden=e.target.value!=='공지사항';if(label.hidden)label.querySelector('input').checked=false});$('#post-pin-label').hidden=e.target.value!=='공지사항';if(e.target.value!=='공지사항')$('#post-pin-label input').checked=false}});

function loginPage(){return `<section class="login-shell"><div class="login-art"><div class="login-stripes"></div><span class="brand-mark login-logo" role="img" aria-label="ONOFF CROSSFIT"><img src="assets/onoff-logo.png?v=2" alt=""></span><div class="login-location">ILGWANG, BUSAN · CROSSFIT COMMUNITY</div><div class="login-statement">Challenge<br>starts <span>Today.</span></div><div class="login-caption">오늘의 움직임이 내일의 나를 바꿉니다.</div><div class="login-coordinates">MOVE TOGETHER. GROW TOGETHER.</div></div><div class="login-card"><div class="eyebrow">WELCOME TO ONOFF</div><h1>함께 켜는<br>우리의 운동 시간.</h1><button class="btn kakao login-kakao" data-action="kakao">카카오로 시작하기 <span>↗</span></button><p class="login-description">오늘의 운동을 확인하고,<br>나의 기록과 성장을 쌓아보세요.</p><div class="login-benefits"><span>${icon('calendar')} 오늘의 B/T · WOD</span><span>${icon('weight')} 나의 운동 기록 · 1RM</span><span>${icon('users')} 함께하는 온오프 커뮤니티</span></div><p class="login-auth-note">카카오 계정 연결은 준비 중입니다.<br>현재는 비공개 미리보기 계정으로 확인할 수 있어요.</p>${viewer?`<button class="btn primary login-enter" data-page="home">${globalThis.ONOFF_DEMO?'테스트 앱 열기':esc(viewer.name)+'님, 앱 열기'} ${icon('arrow')}</button>`:loading?'<div class="login-auth-note">현재 계정을 확인하고 있어요…</div>':`<a class="btn primary login-enter" href="/signin-with-chatgpt?return_to=/%23home" target="_top">미리보기 계정으로 로그인</a>`}<p class="login-approval">가입 후 운영자 승인으로 함께하는<br>온오프 회원 전용 공간입니다.</p>${privacyLinks()}</div></section>`;}

function pushSettings(){const support=pushSupport();return `<div class="push-settings"><div class="setting-row"><div><strong>웹 푸시 알림</strong><p>${devicePushEnabled?'이 기기에서 알림을 받고 있어요.':support.ok?'중요한 소식을 앱 밖에서도 받아보세요.':esc(support.reason)}</p></div><button class="btn ${devicePushEnabled?'soft':'primary'}" data-action="push-toggle" ${!devicePushEnabled&&(!support.ok||!pushState.configured)?'disabled':''}>${devicePushEnabled?'알림 끄기':'알림 켜기'}</button></div>${!pushState.configured?'<p class="field-hint">알림 서버 연결을 준비 중입니다.</p>':''}<div class="setting-row"><div><strong>운영자 공지</strong><p>운영자가 알림 보내기를 선택한 공지</p></div><button class="switch ${pushPreferences.notices?'on':''}" role="switch" aria-checked="${!!pushPreferences.notices}" aria-label="운영자 공지 알림" data-push-pref="notices"></button></div><div class="setting-row"><div><strong>내일 운동 공개 알림</strong><p>${pushState.schedulerConfigured?'설정한 공개 시각에 알려드려요.':'자동 발송 예약 연결 전 · 현재는 공지와 시험 알림 사용 가능'}</p></div><button class="switch ${pushPreferences.workouts?'on':''}" role="switch" aria-checked="${!!pushPreferences.workouts}" aria-label="운동 공개 알림" data-push-pref="workouts"></button></div>${devicePushEnabled?'<button class="btn soft" data-action="push-test">내 기기에 시험 알림 보내기</button>':''}</div>`;}
Object.assign(actions,{'push-toggle':async()=>{const button=$('[data-action="push-toggle"]');if(button)button.disabled=true;try{if(devicePushEnabled){await disablePush(request);devicePushEnabled=false;toast('이 기기의 알림을 껐어요.')}else{await enablePush(pushState.publicKey,pushPreferences,request);devicePushEnabled=true;toast('이 기기에서 알림을 받을 수 있어요.')}render();}catch(e){toast(e.message);if(button)button.disabled=false}},'push-test':async()=>{try{const result=await request('/api/push/test',{});toast(result.sent?'시험 알림을 보냈어요.':'전송을 확인하지 못했어요. 알림 설정을 확인해주세요.')}catch(e){toast(e.message)}}});
document.addEventListener('click',async e=>{const kind=e.target.closest('[data-push-pref]')?.dataset.pushPref;if(!kind)return;const previous={...pushPreferences};pushPreferences[kind]=!pushPreferences[kind];try{const sub=await deviceSubscription();if(sub)await request('/api/push/subscribe',{subscription:sub.toJSON(),preferences:pushPreferences});localStorage.setItem('onoff-push-preferences',JSON.stringify(pushPreferences));render()}catch(e){pushPreferences=previous;toast(e.message)}});

function backTo(target,label){return `<button class="back-link" data-page="${target}">${icon('arrow')} ${label}</button>`;}
function folderCard(target,ic,title,description,meta){
  const tone={personCheck:'mint',calendarEdit:'blue',clipboard:'violet',play:'rose',calendar:'amber',megaphone:'amber',clock:'blue',chart:'blue',weight:'violet'}[ic]||'blue';
  const pending=target==='admin/members'&&pendingMembers()>0;
  return `<button class="panel folder-card menu-card ${pending?'needs-attention':''}" data-page="${target}"><span class="feature-icon feature-${tone}">${icon(ic)}</span><span class="folder-copy"><strong>${title}</strong><span>${description}</span><small class="${pending?'pending-label':''}">${pending?'<i></i>':''}${meta}</small></span><span class="folder-arrow">${icon('arrow')}</span></button>`;
}
function bannerMarkup(b,preview=false){
  const color=['blue','mint','amber'].includes(b.color)?b.color:'blue';
  return `<div class="notice notice-${color} ${preview?'banner-preview':''}" style="--notice-duration:${Math.max(24,Math.min(120,b.text.length*.3))}s"><span>${icon('bell')} 공지</span><div class="notice-track"><div class="notice-text"><span>${esc(b.text)}</span><span aria-hidden="true">${esc(b.text)}</span></div></div>${preview?'':`${viewer?.role==='admin'&&!memberPreview?'<button class="banner-manage" data-page="admin/banner" aria-label="홈 공지 배너 설정">설정</button>':''}<button data-action="notice" aria-label="공지 전체 내용 보기">${icon('arrow')}</button>`}</div>`;
}
function homeBanner(){return bannerState.enabled?bannerMarkup(bannerState):'';}
function updateCalculator(){
  const out=$('#calc-answer'),input=$('#calc-percent'),b=best(calculatorMovement);if(!out||!input||!b)return;
  const raw=input.value,n=Number(raw),value=percentageWeight(b.lbs,n,state.unit);
  if(raw===''||value===null){out.textContent='1~150% 사이의 비율을 입력해주세요.';return;}
  calculatorPercent=n;
  out.innerHTML=`<span>${n}% 중량</span><strong>${Number(value.toFixed(1)).toLocaleString('en-US')} <small>${state.unit}</small></strong><small>≈ ${Number(percentageWeight(b.lbs,n,state.unit==='lbs'?'kg':'lbs').toFixed(1))} ${state.unit==='lbs'?'kg':'lbs'}</small>`;
  document.querySelectorAll('[data-percent]').forEach(b=>b.classList.toggle('active',+b.dataset.percent===n));
}
function adminContent(section){
  if(section==='tv')return tvAdminPage();
  if(section==='workouts')return `<div class="settings-grid"><section class="panel settings-section"><h2>엑셀로 수업 일괄 등록</h2><p class="field-hint">한 행에 한 구간을 입력하고, 업로드 후 미리보기를 확인해주세요.</p><div class="excel-actions"><a class="btn soft" href="assets/onoff-workouts-template.xlsx?v=3" download>↓ 빈 양식 다운로드</a><a class="btn" href="assets/onoff-workouts-example.xlsx?v=3" download>예시 파일</a></div><div class="upload-zone"><label class="btn primary" for="excel-file">${icon('plus')}엑셀 파일 선택</label><input type="file" accept=".xlsx" id="excel-file" hidden><small>.xlsx · 최대 3MB / 1,000행</small></div></section><section class="panel settings-section"><h2>날짜별 수업 등록·수정</h2><p class="field-hint">공개 전에도 운동 내용을 수정할 수 있어요.</p>${datePicker()}<div class="admin-actions"><button class="btn primary" data-edit-workout="WOD">WOD 등록·수정</button><button class="btn soft" data-edit-workout="B/T">B/T 등록·수정</button></div><p class="field-hint">수요일은 WOD 수업만 운영합니다.<br>공휴일 특별 수업은 시작 시각도 지정해주세요.</p></section></div>`;
  if(section==='schedule')return `<section class="panel settings-section"><h2>등록된 수업 · ${Object.keys(state.workouts).length}개</h2>${Object.values(state.workouts).sort((a,b)=>a.date.localeCompare(b.date)||a.program.localeCompare(b.program)).map(w=>`<div class="history-row"><div>${esc(w.date)} · ${w.program}<small>${isReleased(w.date,serverNow())?'회원 공개 중':addDays(w.date,-1)+' '+releaseTime+' 공개 예정'} · ${w.sections.length}개 구간</small></div><button class="link" data-workout-date="${w.date}" data-workout-program="${w.program}">수정 ↗</button></div>`).join('')||'<div class="empty">아직 등록된 수업이 없어요.<br><button class="btn primary" data-page="admin/workouts">수업 등록하기</button></div>'}</section>`;
  if(section==='entry')return batchEntryPage();
  if(section==='videos')return `<section class="panel settings-section"><h2>동작마다 연결되는 코칭 영상</h2><p class="field-hint">운동 사전에 유튜브 주소를 한 번 등록하면 관련 동작이 지정된 수업에서 영상을 볼 수 있어요.</p><button class="btn primary" data-page="library">${icon('weight')} 운동 사전·영상 관리</button></section>`;
  if(section==='calendar')return `<section class="panel settings-section"><h2>대한민국 공휴일 달력</h2><p class="field-hint">공휴일·대체공휴일은 기본 휴강입니다. 해당 날짜에 운동 내용과 시작 시각을 등록하면 특별 수업으로 표시됩니다.</p><p class="field-hint">${esc(holidayState.source)} · ${holidayState.updatedAt?holidayState.updatedAt.slice(0,10):'저장된 일정'}</p><div class="admin-actions"><button class="btn soft" data-action="calendar">공휴일 달력 보기</button>${viewer.role==='admin'?'<button class="btn" data-action="sync-holidays">일정 새로고침</button>':''}</div></section>`;
  if(section==='release')return `<section class="panel settings-section narrow-panel"><h2>다음 날 운동 공개</h2><div class="public-time">${releaseTime} <span class="small-label">KST · 매일</span></div><form id="release-time-form"><label class="field">내일 운동 공개 시각<input name="releaseTime" type="time" required value="${releaseTime}"></label><p class="field-hint">아직 공개되지 않은 수업부터 적용합니다. 이미 공개된 수업은 유지됩니다.</p><button class="btn primary">공개 시각 저장</button></form><p class="field-hint">수업 날짜 전날 설정 시각에 자동 공개됩니다.</p></section>`;
  if(section==='banner')return `<section class="panel settings-section banner-editor"><h2>홈 화면 상단 공지</h2><p class="field-hint">운영자만 수정할 수 있어요. 저장한 배너는 회원의 홈 상단에 표시됩니다.</p><form id="banner-form"><label class="checkbox-label banner-enabled-label"><input name="enabled" id="banner-enabled" type="checkbox" ${bannerState.enabled?'checked':''}>홈에 공지 배너 표시</label><label class="field">공지 문구<textarea name="text" id="banner-text" required maxlength="500" rows="3">${esc(bannerState.text)}</textarea></label><p class="field-hint" id="banner-length">${bannerState.text.length} / 500자</p><fieldset class="banner-colors"><legend>배너 색상</legend>${[['blue','블루'],['mint','민트'],['amber','앰버']].map(([value,label])=>`<label class="color-choice color-${value}"><input type="radio" name="color" value="${value}" ${bannerState.color===value?'checked':''}><span>${label}</span></label>`).join('')}</fieldset><div class="banner-preview-label">미리보기 · 저장 전</div><div id="banner-preview">${bannerMarkup(bannerState,true)}</div><button class="btn primary full">배너 설정 저장</button></form></section>`;
  if(section==='members')return memberManagerPage();
  return '';
}

function batchContext(){
  if(!batchDate)batchDate=today();if(!batchUnit)batchUnit=state.unit;
  const sessions=schedule(batchDate).filter(s=>s.type===batchProgram);
  if(!sessions.some(s=>s.time===batchSession))batchSession=sessions[0]?.time||'';
  const w=workout(batchProgram,batchDate),sections=w.sections.map((s,i)=>({...s,key:'S'+(i+1)})).filter(s=>s.record);
  if(!sections.some(s=>s.key===batchSection))batchSection=sections[0]?.key||'';
  return{date:batchDate,program:batchProgram,session:batchSession,section:batchSection,unit:batchUnit,sectionData:sections.find(s=>s.key===batchSection),sessions,sections};
}
function batchKey(c){return [c.date,c.program,c.session,c.section].join('|');}
function batchMembers(){return state.members.filter(m=>m.status==='approved').slice().sort((a,b)=>a.name.localeCompare(b.name,'ko'));}
function batchEntryPage(){
  const c=batchContext(),members=batchMembers(),draft=batchDrafts.get(batchKey(c)),isWeight=['중량','1RM'].includes(c.sectionData?.kind);
  return `<section class="panel settings-section batch-panel"><div class="preview-note">현재 기록은 이 브라우저에만 저장됩니다. 회원 간 공유는 Supabase 연결 후 사용할 수 있어요.</div><form id="batch-form" data-date="${c.date}" data-program="${c.program}" data-session="${c.session}" data-section="${c.section}" data-unit="${c.unit}"><div class="batch-filters"><label class="field">운동 날짜<input id="batch-date" data-unsaved-ignore type="date" value="${c.date}" max="${today()}" required></label><label class="field">수업<select id="batch-program" data-unsaved-ignore><option ${c.program==='WOD'?'selected':''}>WOD</option><option ${c.program==='B/T'?'selected':''}>B/T</option></select></label><label class="field">시작 시간<select id="batch-session" data-unsaved-ignore>${c.sessions.length?c.sessions.map(s=>`<option ${s.time===c.session?'selected':''}>${s.time}</option>`).join(''):'<option value="">정규 수업 없음</option>'}</select></label><label class="field">기록 구간<select id="batch-section" data-unsaved-ignore>${c.sections.length?c.sections.map(s=>`<option value="${s.key}" ${s.key===c.section?'selected':''}>${s.key} · ${esc(s.kind)}</option>`).join(''):'<option value="">기록 구간 없음</option>'}</select></label>${isWeight?`<label class="field">입력 단위<select id="batch-unit" data-unsaved-ignore><option ${c.unit==='lbs'?'selected':''}>lbs</option><option ${c.unit==='kg'?'selected':''}>kg</option></select></label>`:''}</div>${!c.session||!c.sectionData?'<div class="empty">선택한 날짜·수업에 입력할 기록이 없어요.<br>정규 수업이 있는 날짜를 선택하고, 수업 등록 시 기록 구간을 지정해주세요.</div>':`<div class="batch-workout-summary"><span class="tag">${esc(c.section)}</span><strong>${esc(c.sectionData.title)}</strong><span>${esc(c.sectionData.kind)}${isWeight?' · '+c.unit:''}</span></div><p class="field-hint">값을 입력한 회원만 저장됩니다. 빈칸은 기존 기록을 지우지 않아요. Enter를 누르면 다음 회원으로 이동합니다.</p><label class="field">회원 찾기<input id="batch-search" data-unsaved-ignore type="search" value="${esc(batchSearch)}" placeholder="이름 검색 · 입력한 다른 회원의 기록도 함께 저장돼요."></label><div class="batch-rows">${members.map(m=>{const old=findClassRecord(state.records,m,c),entry=draft?.rows[m.id];const canonicalLbs=entry?.canonicalLbs??(isWeight?old?.lbs:undefined);let value=entry?.value??(old?isWeight&&old.lbs!=null?String(Number(fromLbs(old.lbs,c.unit).toFixed(1))):old.value||'':'');if(entry&&draft.unit!==c.unit&&isWeight&&value&&Number.isFinite(canonicalLbs))value=String(Number(fromLbs(canonicalLbs,c.unit).toFixed(1)));const note=entry?.note??old?.note??'';return `<div class="batch-row" data-batch-member="${esc(m.id)}" data-member-name="${esc(m.name.toLowerCase())}" ${!m.name.toLowerCase().includes(batchSearch.toLowerCase())?'hidden':''}><div class="batch-member"><span class="avatar">${esc(m.name.slice(0,1))}</span><strong>${esc(m.name)}</strong>${m.note?`<small class="member-note">${esc(m.note)}</small>`:''}${old?'<span class="mini-badge">저장됨</span>':''}</div><label class="field"><span>${isWeight?'중량 ('+c.unit+')':esc(c.sectionData.kind)}</span><input data-batch-value data-original-value="${esc(value)}" data-canonical-lbs="${Number.isFinite(canonicalLbs)?canonicalLbs:''}" aria-label="${esc(m.name)} 기록" ${isWeight?'type="number" min="0.000001" max="3000" step="any" inputmode="decimal"':'type="text" maxlength="120"'} value="${esc(value)}" placeholder="${isWeight?'예: 135':c.sectionData.kind==='시간'?'예: 09:35':c.sectionData.kind==='세트별 횟수·칼로리'?'예: 12 / 21 / 10 / 19 / 8 / 18':'운동 결과'}"></label><label class="field batch-note"><span>메모 (선택)</span><input data-batch-note aria-label="${esc(m.name)} 메모" value="${esc(note)}" maxlength="150" placeholder="중량·변경 동작 등"></label></div>`}).join('')||'<div class="empty">승인된 회원이 없어요.</div>'}</div><div id="batch-no-match" class="empty" ${members.some(m=>m.name.toLowerCase().includes(batchSearch.toLowerCase()))?'hidden':''}>검색된 회원이 없어요.</div><label class="checkbox-label"><input id="batch-overwrite" type="checkbox">이 수업에 이미 저장된 기록의 수정 허용</label><div id="batch-errors" role="alert" tabindex="-1"></div><div class="batch-save"><span id="batch-count" role="status"></span><button class="btn primary" id="batch-save" ${members.length?'':'disabled'}>${icon('check')}입력한 기록 저장</button></div>`}</form></section>`;
}
function formBatchContext(f){const c={date:f.dataset.date,program:f.dataset.program,session:f.dataset.session,section:f.dataset.section,unit:f.dataset.unit};c.sectionData=workout(c.program,c.date).sections[Number(c.section.slice(1))-1];return c;}
function collectBatchRows(f){const members=batchMembers();return [...f.querySelectorAll('[data-batch-member]')].map(row=>{const member=members.find(m=>m.id===row.dataset.batchMember),input=row.querySelector('[data-batch-value]'),canonicalLbs=input.value===input.dataset.originalValue&&input.dataset.canonicalLbs!==''?Number(input.dataset.canonicalLbs):undefined;return{member,value:input.value,canonicalLbs,note:row.querySelector('[data-batch-note]').value,rank:member?.id===viewer.id&&state.rank};});}
function rememberBatch(){const f=$('#batch-form');if(!f)return;const c=formBatchContext(f);batchDrafts.set(batchKey(c),{unit:c.unit,rows:Object.fromEntries(collectBatchRows(f).filter(r=>r.member).map(r=>[r.member.id,{value:r.value,note:r.note,canonicalLbs:r.canonicalLbs??(r.value.trim()&&Number.isFinite(Number(r.value))?toLbs(r.value,c.unit):undefined)}]))});}
function updateBatchCount(){const f=$('#batch-form'),out=$('#batch-count');if(!f||!out)return;const rows=collectBatchRows(f),count=rows.filter(r=>r.value.trim()).length;out.textContent=count+'명 입력됨';}
async function extraForm(f,data){
  if(await gymForm(f,data))return true;

  if(f.id==='banner-form'){
    if(viewer?.role!=='admin'||memberPreview){toast('운영자만 공지 배너를 수정할 수 있어요.');return true;}
    const submit=f.querySelector('button');submit.disabled=true;
    try{await request('/api/banner',{enabled:data.enabled==='on',text:data.text,color:data.color});await loadServer(false);toast('홈 공지 배너를 저장했어요.');}catch(e){toast(e.message);submit.disabled=false;}
    return true;
  }
  if(f.id!=='batch-form')return false;
  if(!coach||memberPreview){toast('운영자 권한이 필요해요.');return true;}
  const c=formBatchContext(f),output=$('#batch-errors');
  if(!schedule(c.date).some(s=>s.time===c.session&&s.type===c.program)){output.textContent='선택한 날짜의 수업 시간을 확인해주세요.';output.focus();return true;}
  const result=prepareBatchRecords({rows:collectBatchRows(f),context:c,records:state.records,today:today(),overwrite:!!$('#batch-overwrite')?.checked});
  if(result.errors.length){output.innerHTML='<ul>'+result.errors.map(e=>'<li>'+esc(e)+'</li>').join('')+'</ul>';output.focus();return true;}
  if(!result.changes.length){toast('새로 입력하거나 변경한 기록이 없어요.');return true;}
  const oldRecords=state.records,oldRms=state.rms;
  try{
    const ids=new Set(result.changes.map(r=>r.id));
    state.records=[...state.records.filter(r=>!ids.has(r.id)),...result.changes];
    state.rms=state.rms.filter(r=>!ids.has(r.source));
    for(const r of result.changes)if(r.kind==='1RM'&&r.memberId===viewer.id&&r.lbs)state.rms.push({id:crypto.randomUUID(),source:r.id,movement:r.movement,lbs:r.lbs,date:r.date});
    save();batchDrafts.delete(batchKey(c));render();toast(result.changes.length+'명의 기록을 저장했어요.');
  }catch(e){state.records=oldRecords;state.rms=oldRms;output.textContent='기록을 저장하지 못했어요. 입력 내용은 유지됩니다.';output.focus();}
  return true;
}
document.addEventListener('input',e=>{
  if(e.target.id==='calc-percent')updateCalculator();
  if(e.target.matches('[data-batch-value],[data-batch-note]')){rememberBatch();updateBatchCount();}
  if(e.target.id==='batch-search'){batchSearch=e.target.value;const rows=[...document.querySelectorAll('[data-batch-member]')];rows.forEach(row=>row.hidden=!row.dataset.memberName.includes(batchSearch.toLowerCase()));$('#batch-no-match').hidden=rows.some(r=>!r.hidden);}
  if(e.target.closest('#banner-form')){const f=$('#banner-form');$('#banner-length').textContent=f.elements.text.value.length+' / 500자';$('#banner-preview').innerHTML=bannerMarkup({text:f.elements.text.value,color:f.elements.color.value},true);}
});
document.addEventListener('change',e=>{
  if(!['batch-date','batch-program','batch-session','batch-section','batch-unit'].includes(e.target.id))return;
  rememberBatch();
  if(e.target.id==='batch-date')batchDate=e.target.value||today();
  if(e.target.id==='batch-program')batchProgram=e.target.value;
  if(e.target.id==='batch-session')batchSession=e.target.value;
  if(e.target.id==='batch-section')batchSection=e.target.value;
  if(e.target.id==='batch-unit')batchUnit=e.target.value;
  render();
});
document.addEventListener('keydown',e=>{
  if(e.key!=='Enter'||e.isComposing||!e.target.matches('[data-batch-value],[data-batch-note]'))return;
  e.preventDefault();const rows=[...document.querySelectorAll('[data-batch-member]:not([hidden])')],index=rows.indexOf(e.target.closest('[data-batch-member]'));
  if(index<rows.length-1)rows[index+1].querySelector('[data-batch-value]').focus();else $('#batch-save').focus();
});

function pendingMembers(){return state.members.filter(m=>m.status==='pending').length;}
function approvalBadge(){const n=pendingMembers();return viewer?.role==='admin'&&!memberPreview&&n?`<span class="approval-count" aria-label="승인 대기 ${n}명">${n>99?'99+':n}</span>`:'';}
function memberManagerPage(){return fullMemberManager();}
function renderMemberResults(){
  if(!$('#member-results'))return;
  $('#member-results').innerHTML=memberRows();
  document.querySelectorAll('[data-member-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.memberFilter===memberFilter);b.setAttribute('aria-pressed',String(b.dataset.memberFilter===memberFilter));});
}
async function approveMember(id){
  if(viewer?.role!=='admin'||memberPreview)return;
  const member=state.members.find(m=>m.id===id);if(!member||member.id===viewer.id||member.status!=='pending')return;
  const button=[...document.querySelectorAll('[data-member-approve]')].find(b=>b.dataset.memberApprove===id);if(button){button.disabled=true;button.setAttribute('aria-busy','true');}
  try{await request('/api/members',{id,role:'member',status:'approved'});await loadServer(false);toast(member.name+'님의 가입을 승인했어요.');}
  catch(e){toast(e.message);if(button){button.disabled=false;button.removeAttribute('aria-busy');}}
}
function batchHasUnsaved(){
  for(const [key,draft] of batchDrafts){
    const [date,program,session,section]=key.split('|'),rows=Object.entries(draft.rows).map(([id,entry])=>({...entry,member:state.members.find(m=>m.id===id)}));
    if(!rows.some(r=>r.value.trim()||r.note.trim()))continue;
    const sectionData=workout(program,date).sections[Number(section.slice(1))-1];
    const result=prepareBatchRecords({rows,context:{date,program,session,section,unit:draft.unit,sectionData},records:state.records,today:today(),overwrite:true});
    if(result.errors.length||result.changes.length)return true;
  }
  return false;
}
document.addEventListener('input',e=>{if(e.target.id==='member-search'){memberSearch=e.target.value;renderMemberResults();}});
window.addEventListener('beforeunload',e=>{if(unsaved.hasChanges()){e.preventDefault();e.returnValue='';}});
$('#modal').addEventListener('cancel',e=>{if(!unsaved.allow($('#modal-body'),false))e.preventDefault();});

function memberRows(){return fullMemberRows();}
function memberDetail(id){return fullMemberDetail(id);}

function ownPass(){return memberships.find(p=>p.user_id===viewer?.id)||selfMembership;}
function memberPass(id){return memberships.find(p=>p.user_id===id)||(id===viewer?.id?selfMembership:null);}
function passInfoHtml(pass){const info=membershipState(pass,today(),pass?.user_id===viewer?.id&&selfMembershipAccess&&state.attendance.includes(today()));return `<div class="pass-summary"><span class="pass-status ${info.status}">${info.label}</span><strong>${membershipTitle(pass)}</strong>${pass?`<p>${pass.start_date}부터 ${pass.end_date?pass.end_date+'까지':'유효기간 제한 없음'}</p>${pass.kind==='visits'?`<p><b>${pass.remaining_visits}회 남음</b> · 하루 여러 수업에 참여해도 1회 차감</p>`:info.days>0?`<p>${info.days}일 남음</p>`:''}${pass.paused_at?`<p>${pass.paused_at}부터 휴회 중</p>`:''}`:'<p>운영자가 회원권을 등록하면 기간과 잔여횟수가 표시돼요.</p>'}</div>`;}
function themeChoices(){return `<div class="theme-options">${THEMES.map(t=>`<button class="theme-choice" data-app-theme="${t.id}" aria-pressed="${document.documentElement.dataset.theme===t.id}"><span class="theme-swatch" style="--swatch-bg:${t.background};--swatch-accent:${t.accent}">ONOFF</span>${t.name}</button>`).join('')}</div>`;}
function accountSettings(){return `${intro('나에게 맞는 온오프','회원권과 운동 환경을 한곳에서 확인하세요.')}<div class="settings-stack"><section class="panel"><h2>내 회원권</h2>${passInfoHtml(ownPass())}${globalThis.ONOFF_DEMO?'<p class="field-hint">공개 테스트에서 변경한 회원권은 현재 브라우저에 저장됩니다.</p>':''}</section><section class="panel"><h2>앱 테마</h2><p class="field-hint">네이비 블루 · 블랙 민트 · 차콜 오렌지<br>로고와 메뉴 색상이 함께 바뀌고 다음 접속에도 유지됩니다.</p>${themeChoices()}<div class="setting-row"><div><strong>기본 중량 단위</strong><p>같은 무게를 lbs 또는 kg으로 표시해요.</p></div>${unitToggle()}</div></section><section class="panel"><h2>순위 참여</h2><div class="setting-row"><div><strong>순위에 내 기록 포함</strong><p>순위 참여를 꺼도 운동 기록은 다른 회원에게 보여요.</p></div><button class="switch ${state.rank?'on':''}" role="switch" aria-checked="${state.rank}" aria-label="순위 참여" data-action="rank"></button></div></section><section class="panel"><details class="notification-details"><summary>알림 설정 <span class="tag">${devicePushEnabled?'켜짐':'꺼짐'} ⌄</span></summary>${pushSettings()}</details></section><section class="panel"><h2>계정</h2><div class="setting-row"><div><strong>${esc(state.name)}</strong><p>${viewer?.role==='admin'?'운영자':'회원'} · ${viewer?.status==='approved'?'승인 완료':'승인 대기'}</p></div><button class="btn" data-action="name">이름 수정</button></div><p class="field-hint">카카오 로그인은 연결 준비 중입니다.</p>${coach&&!memberPreview?'<button class="btn soft" data-page="admin">운영 메뉴 열기</button>':''}</section><section class="panel"><h2>개인정보와 계정 관리</h2><p class="field-hint">운영자 정보와 보관·삭제 기준을 확정하기 위한 초안입니다.</p>${privacyLinks()}<button class="link withdrawal-link" data-action="withdrawal">회원 탈퇴 안내 · 연결 준비 중</button></section></div>`;}
function passAllowsToday(){return coach&&!memberPreview||selfMembershipAccess;}

function passBlockedView(){const p=ownPass();return `${intro('회원권을 확인해주세요.','운영자에게 연장 또는 휴회 상태를 확인해주세요.')}<section class="panel settings-section">${passInfoHtml(p)}<p class="field-hint">지난 나의 운동 기록과 1RM은 계속 확인할 수 있어요.</p><button class="btn primary" data-page="records">내 기록 보기</button></section>`;}
function passFilterMatches(member,filter){if(['pending','suspended'].includes(filter))return member.status===filter;if(member.status!=='approved')return false;const info=membershipState(memberPass(member.id),today());return filter==='approved'?['active','unregistered','scheduled'].includes(info.status):filter==='soon'?info.soon:info.status===filter;}
function fullMemberManager(){return `<section class="panel settings-section member-manager"><div class="member-heading"><div><h2>회원·회원권 관리</h2><p class="field-hint">기간권·횟수권 등록, 연장과 휴회·재개를 관리하세요.</p></div>${pendingMembers()?`<span class="pending-pill">승인 대기 ${pendingMembers()}명</span>`:'<span class="complete-pill">모든 회원 승인 완료</span>'}</div><div class="filter-tabs member-status-tabs" role="group" aria-label="회원 상태">${[['pending','승인 대기'],['approved','이용 중'],['soon','만료 예정'],['expired','만료'],['paused','휴회'],['suspended','이용 중지']].map(([value,label])=>`<button data-member-filter="${value}" aria-pressed="${memberFilter===value}" class="${memberFilter===value?'active':''}">${label}<span>${state.members.filter(m=>passFilterMatches(m,value)).length}</span></button>`).join('')}</div><label class="field member-search-label">회원 이름·구분 메모 검색<input type="search" id="member-search" class="search-input" value="${esc(memberSearch)}" placeholder="이름이나 운영자용 구분 메모로 찾기"></label><div id="member-results">${fullMemberRows()}</div></section>`;}
function fullMemberRows(){const search=memberSearch.trim().toLowerCase(),rows=state.members.filter(m=>passFilterMatches(m,memberFilter)&&(m.name+' '+(m.note||'')).toLowerCase().includes(search));if(!rows.length)return `<div class="empty member-empty">${icon('personCheck')}<strong>${search?'검색된 회원이 없어요.':'해당 상태의 회원이 없어요.'}</strong>${memberFilter==='pending'?'<p>가입 신청이 들어오면 여기에 표시돼요.</p><button class="btn soft" data-member-filter="approved">이용 중인 회원 보기</button>':''}</div>`;return `<p class="member-result-count" role="status">${rows.length}명의 회원</p>${rows.map(m=>{const p=memberPass(m.id),info=membershipState(p,today());return `<div class="member-row"><div class="member-identity"><span class="avatar">${esc(m.name.slice(0,1))}</span><div><strong>${esc(m.name)}${m.id===viewer.id?'<span class="self-label">내 계정</span>':''}</strong><p>${membershipTitle(p)}${p?' · '+(p.kind==='visits'?p.remaining_visits+'회 남음':p.end_date+'까지'):''} · ${m.status==='approved'?info.label:m.status==='pending'?'승인 대기':'이용 중지'}</p>${m.note?`<div class="member-note">${esc(m.note)}</div>`:''}</div></div><div class="member-row-actions">${m.status==='pending'?`<button class="btn primary" data-member-approve="${esc(m.id)}">${icon('check')}승인</button>`:''}<button class="btn soft" data-member-detail="${esc(m.id)}">회원권·상세</button></div></div>`}).join('')}`;}
function fullMemberDetail(id){if(viewer?.role!=='admin'||memberPreview)return;const m=state.members.find(m=>m.id===id);if(!m)return;const p=memberPass(id),history=membershipEvents.filter(e=>e.user_id===id).slice(0,30);modal('회원 관리',`<div class="member-detail-name">${esc(m.name)}</div>${passInfoHtml(p)}<section class="membership-section"><h3>운영자용 구분 메모</h3><form id="member-note-form" data-member-id="${esc(id)}"><label class="field">동명이인 구분 등 · 회원에게는 공개되지 않습니다<textarea name="note" maxlength="500" rows="2" placeholder="예: 주로 오전 방문">${esc(m.note||'')}</textarea></label><button class="btn soft">메모 저장</button></form></section><details class="membership-section" open><summary>회원권 등록·연장</summary><form id="membership-form" data-member-id="${esc(id)}"><label class="field">작업<select name="action" id="pass-action"><option value="register">새 회원권 등록</option>${p?`<option value="extend" ${!p.paused_at?'selected':''}>현재 회원권 연장</option>`:''}</select></label><div class="field-row"><label class="field">회원권 종류<select name="kind" id="pass-kind"><option value="period" ${p?.kind==='period'?'selected':''}>기간권</option><option value="visits" ${p?.kind==='visits'?'selected':''}>횟수권</option></select></label><label class="field" data-pass-period>기간<select name="months" id="pass-months">${[1,3,6,12].map(n=>`<option value="${n}" ${p?.months===n?'selected':''}>${n===12?'1년':n+'개월'}</option>`).join('')}</select></label><label class="field" data-pass-visits>추가 횟수<input name="visits" type="number" min="1" max="9999" value="10"></label></div><div class="field-row"><label class="field">시작일<input name="startDate" id="pass-start" type="date" required value="${today()}"></label><label class="field">종료일 · 횟수권은 선택<input name="endDate" id="pass-end" type="date"></label></div><div class="membership-preview" id="pass-preview"></div><p class="field-hint">현재 회원권 연장은 같은 종류로 처리됩니다. 새 회원권 등록을 선택하면 이전 회원권을 대체하며 이력은 유지됩니다.</p><button class="btn primary full">회원권 저장</button></form></details>${p?`<section class="membership-section"><h3>휴회·재개</h3><p class="field-hint">휴회 중에는 이용을 멈추고, 재개할 때 휴회한 일수만큼 종료일을 연장합니다. 잔여횟수는 그대로 유지됩니다.</p><div class="membership-buttons"><button class="btn soft" data-pass-action="${p.paused_at?'resume':'pause'}" data-member-id="${esc(id)}">${p.paused_at?'운동 재개':'휴회 시작'}</button></div></section><details class="membership-section"><summary>종료일·잔여횟수 직접 수정</summary><form id="membership-adjust-form" data-member-id="${esc(id)}"><label class="field">종료일<input type="date" name="endDate" value="${p.end_date||''}" ${p.kind==='period'?'required':''}></label>${p.kind==='visits'?`<label class="field">잔여횟수<input type="number" name="remaining" min="0" max="9999" value="${p.remaining_visits}" required></label>`:''}<label class="field">수정 사유<input name="reason" required maxlength="200" placeholder="수정 내역에 남길 사유"></label><button class="btn primary full">수정 저장</button></form></details>`:''}<details class="membership-section"><summary>출석 취소·횟수 복구</summary><p class="field-hint">현재 회원권에서 차감한 출석이면 1회를 복구합니다. 이전 회원권에서 차감한 횟수는 현재 회원권에 더하지 않습니다.</p><form id="attendance-cancel-form" data-member-id="${esc(id)}"><label class="field">취소할 출석 날짜<input type="date" name="date" max="${today()}" value="${today()}" required></label><label class="field">취소 사유<input name="reason" required maxlength="200"></label><button class="btn soft full">출석 취소</button></form></details><details class="membership-section"><summary>회원권 변경 이력 · ${history.length}건</summary><div class="membership-history">${history.map(e=>{let body={};try{body=JSON.parse(e.body)}catch{}return `<div><strong>${({register:'회원권 등록',extend:'회원권 연장',pause:'휴회 시작',resume:'운동 재개',adjust:'직접 수정','attendance-cancel':'출석 취소'})[e.action]||esc(e.action)}</strong><small>${esc(e.created_at.slice(0,16).replace('T',' '))}</small>${body.reason?`<p>${esc(body.reason)}</p>`:''}</div>`}).join('')||'<p class="field-hint">아직 변경 이력이 없어요.</p>'}</div></details>${id!==viewer.id?`<details class="membership-section"><summary>가입 승인·계정 권한</summary><form id="member-role-form" data-member-id="${esc(id)}"><label class="field">권한<select name="role">${[['member','회원'],['admin','운영자']].map(([v,t])=>`<option value="${v}" ${m.role===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">계정 상태<select name="status">${[['pending','승인 대기'],['approved','승인'],['suspended','이용 중지']].map(([v,t])=>`<option value="${v}" ${m.status===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="btn primary full">권한 저장</button></form></details>`:'<p class="field-hint">자신의 계정 권한은 변경할 수 없습니다.</p>'}`);updatePassPreview(true);queueMicrotask(()=>unsaved.track($('#modal-body')));}
function updatePassPreview(reset=false){const f=$('#membership-form');if(!f)return;const p=memberPass(f.dataset.memberId),kind=f.elements.kind.value,action=f.elements.action.value;f.querySelectorAll('[data-pass-period]').forEach(e=>e.hidden=kind!=='period');f.querySelectorAll('[data-pass-visits]').forEach(e=>e.hidden=kind!=='visits');if(reset){if(kind==='period'){const base=action==='extend'&&p?.end_date>=today()?addDays(p.end_date,1):f.elements.startDate.value;try{f.elements.endDate.value=periodEnd(base,+f.elements.months.value)}catch{}}else f.elements.endDate.value=action==='extend'?p?.end_date||'':'';}$('#pass-preview').textContent=kind==='period'?'종료일: '+(f.elements.endDate.value||'날짜를 선택해주세요.'):'입력한 '+f.elements.visits.value+'회 '+(action==='extend'?'추가 · ':'등록 · ')+(f.elements.endDate.value?f.elements.endDate.value+'까지':'유효기간 제한 없음');}
async function gymForm(f,data){
  const paths={'membership-form':'/api/membership','membership-adjust-form':'/api/membership','member-note-form':'/api/member-note','member-role-form':'/api/members','attendance-cancel-form':'/api/attendance/cancel','tv-admin-form':'/api/tv/admin'};const path=paths[f.id];if(!path)return false;if(f.closest('#modal')&&unsaved.dirtyExcept(f,$('#modal-body'))&&!confirm('다른 항목에 저장하지 않은 내용이 있어요. 해당 내용은 버리고 이 항목만 저장할까요?'))return true;
  if(viewer?.role!=='admin'||memberPreview){toast('운영자 권한이 필요해요.');return true;}
  const payload={...data,id:f.dataset.memberId};if(f.id==='membership-adjust-form')payload.action='adjust';if(f.id==='tv-admin-form')payload.revoke=data.revoke==='on';
  const button=f.querySelector('button');button.disabled=true;try{await request(path,payload);await loadServer(false);close(true);if(f.dataset.memberId)fullMemberDetail(f.dataset.memberId);toast('저장했어요.');}catch(e){toast(e.message);button.disabled=false;}return true;
}
async function passAction(id,action){if(viewer?.role!=='admin'||memberPreview||!unsaved.allow($('#modal-body'),false))return;const p=memberPass(id);if(action==='resume'&&!confirm(`휴회 ${memberDays(p.paused_at,today())}일을 반영해 운동을 재개할까요?`))return;try{await request('/api/membership',{id,action});await loadServer(false);close(true);fullMemberDetail(id);toast(action==='pause'?'휴회를 시작했어요.':'운동을 재개했어요.');}catch(e){toast(e.message)}}
function tvAdminPage(){const prefs=normalizeTvPreferences(tvSettings.preferences||{}),url=new URL('tv.html',location.href.split('#')[0]).href;return `<section class="panel settings-section narrow-panel"><h2>TV 전용 화면</h2><p class="field-hint">B/T와 WOD를 나란히 표시하고, 수요일은 WOD만 표시합니다. 한국 시간 ${releaseTime}부터 다음 날 운동으로 자동 전환합니다.<br>TV 배경은 차콜, 원본 로고·날짜·시간은 화이트로 고정됩니다.</p><div class="tv-admin-preview"><span id="tv-bt-preview" style="background:${TV_COLORS.find(c=>c.id===prefs.btColor).color};color:#111820">B/T</span><span id="tv-wod-preview" style="background:${TV_COLORS.find(c=>c.id===prefs.wodColor).color};color:#111820">WOD</span></div><a class="btn primary" href="./tv.html" target="_blank" rel="noopener">TV 화면 열기 ↗</a><p class="tv-url">${esc(url)}</p>${globalThis.ONOFF_DEMO?'<p class="field-hint">공개 테스트 · 최초 테스트 암호: 0000<br>이 브라우저의 예시 데이터와 설정으로 확인할 수 있어요.</p>':'<p class="field-hint">TV 암호로 접속합니다. 현재 비공개 호스팅의 외부 접속 제한은 유지되며 실제 TV 연결은 공개 인증 서버 연결 후 사용할 수 있습니다.</p>'}<form id="tv-admin-form"><div class="field-row"><label class="field">B/T 색상<select name="btColor" id="tv-bt-color">${TV_COLORS.map(c=>`<option value="${c.id}" ${prefs.btColor===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><label class="field">WOD 색상<select name="wodColor" id="tv-wod-color">${TV_COLORS.map(c=>`<option value="${c.id}" ${prefs.wodColor===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label></div><div class="field-row"><label class="field">중량 단위<select name="unit"><option ${prefs.unit==='lbs'?'selected':''}>lbs</option><option ${prefs.unit==='kg'?'selected':''}>kg</option></select></label><label class="field">긴 운동 페이지 전환<select name="pageSeconds">${[15,20,30,45].map(n=>`<option value="${n}" ${prefs.pageSeconds===n?'selected':''}>${n}초</option>`).join('')}</select></label></div><label class="field">${tvSettings.needsPinUpdate?'TV 암호를 숫자 4자리로 다시 설정해주세요':tvSettings.configured?'새 TV 암호 (변경할 때만 입력)':'TV 암호 설정'}<input type="password" name="password" minlength="4" maxlength="4" pattern="[0-9]{4}" inputmode="numeric" autocomplete="new-password" placeholder="숫자 4자리" ${tvSettings.needsPinUpdate||!globalThis.ONOFF_DEMO&&!tvSettings.configured?'required':''}></label><p class="field-hint">암호를 변경하면 연결된 TV는 다시 접속해야 합니다. TV에서 따로 선택한 색상은 해당 TV에 유지됩니다.</p><label class="checkbox-label"><input type="checkbox" name="revoke">연결된 모든 TV 접속 해제</label><button class="btn primary full">TV 설정 저장</button></form></section>`;}
function recordMemberOptions(existing){const approved=batchMembers(),same=approved.filter(m=>m.name===existing?.name),selected=existing?.memberId||(same.length===1?same[0].id:existing?'':viewer.id);return `<option value="">회원을 선택해주세요.</option>${approved.map(m=>`<option value="${esc(m.id)}" ${m.id===selected?'selected':''}>${esc(m.name)}${m.note?' · '+esc(m.note):''}</option>`).join('')}`;}
document.addEventListener('click',e=>{const d=e.target.closest('button')?.dataset;if(!d)return;if(d.appTheme){if(!unsaved.allow())return;applyTheme(d.appTheme);render();}if(d.passAction)passAction(d.memberId,d.passAction);});
document.addEventListener('change',e=>{if(['pass-action','pass-kind','pass-months','pass-start'].includes(e.target.id))updatePassPreview(true);if(e.target.id==='pass-end')updatePassPreview(false);});
document.addEventListener('input',e=>{if(e.target.closest('#membership-form'))updatePassPreview(false);});

$('#modal').addEventListener('close',()=>document.documentElement.classList.remove('has-modal'));

document.addEventListener('change',e=>{if(['tv-bt-color','tv-wod-color'].includes(e.target.id)){const c=TV_COLORS.find(c=>c.id===e.target.value);const preview=document.getElementById(e.target.id==='tv-bt-color'?'tv-bt-preview':'tv-wod-preview');if(c&&preview)preview.style.background=c.color;}});

Object.assign(actions,{
 'privacy-policy':()=>showPrivacy('policy'),
 'privacy-rights':()=>showPrivacy('rights'),
 'withdrawal':()=>showPrivacy('withdrawal'),
 'scroll-top':()=>{window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('.app-header a')?.focus({preventScroll:true});}
});
function showPrivacy(kind){const doc=privacyDocument(kind);modal(doc.title,doc.html);}
function updateScrollTop(){const b=$('#scroll-top');if(b)b.hidden=window.scrollY<500||page==='login';}
window.addEventListener('scroll',updateScrollTop,{passive:true});
window.addEventListener('hashchange',()=>requestAnimationFrame(updateScrollTop));
function updateHeaderOffset(){document.documentElement.style.setProperty('--app-header-height',($('.app-header')?.getBoundingClientRect().height||0)+'px');}
if('ResizeObserver' in window)new ResizeObserver(updateHeaderOffset).observe($('.app-header'));else window.addEventListener('resize',updateHeaderOffset);
updateHeaderOffset();
